namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public required string Code { get; set; }
    public required string Title { get; set; }
    public required string Description { get; set; }
    public int Credits { get; set; }
    public required string Schedule { get; set; }
    public required string DepartmentCode { get; set; }
    public required string DepartmentName { get; set; }
    public required Instructor Instructor { get; set; }
    public bool IsFeatured { get; set; }
}

namespace UniversityCourseCatalog.Models;

public class Instructor
{
    public required string Name { get; set; }
    public required string Title { get; set; }
    public required string Email { get; set; }
    public required string Bio { get; set; }
}

namespace UniversityCourseCatalog.Models;

public class Department
{
    public required string Code { get; set; }
    public required string Name { get; set; }
    public int CourseCount { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Full name is required.")]
    [StringLength(100)]
    public string FullName { get; set; } = "";

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Z]{2}\d{6}$", ErrorMessage = "Student ID must be 2 uppercase letters followed by 6 digits (e.g., CS123456).")]
    public string StudentId { get; set; } = "";

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public interface ICatalogService
{
    Task<List<Course>> GetCoursesAsync(string? searchTerm = null, string? departmentCode = null);
    Task<Course?> GetCourseByIdAsync(int id);
    Task<List<Course>> GetFeaturedCoursesAsync();
    Task<List<Department>> GetDepartmentsAsync();
    Task<bool> SubmitEnrollmentAsync(EnrollmentRequest request);
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService : ICatalogService
{
    private static readonly List<Course> Courses =
    [
        new()
        {
            Id = 1, Code = "CS101", Title = "Introduction to Computer Science",
            Description = "A foundational course covering computational thinking, basic algorithms, data structures, and programming principles using Python. Students build small projects to reinforce core concepts.",
            Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentCode = "CS", DepartmentName = "Computer Science",
            Instructor = new() { Name = "Dr. Ada Lovelace", Title = "Professor", Email = "alovelace@university.edu", Bio = "Dr. Lovelace has over 15 years of experience teaching introductory CS. Her research focuses on CS education and making computing accessible to all students." },
            IsFeatured = true
        },
        new()
        {
            Id = 2, Code = "CS301", Title = "Database Systems",
            Description = "Relational database design, SQL, normalization, indexing, transactions, and an introduction to NoSQL databases. Includes a semester-long project building a full database-backed application.",
            Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", DepartmentCode = "CS", DepartmentName = "Computer Science",
            Instructor = new() { Name = "Dr. Edgar Codd", Title = "Associate Professor", Email = "ecodd@university.edu", Bio = "Dr. Codd specializes in database theory, query optimization, and distributed data systems. He has published extensively on relational algebra." },
            IsFeatured = false
        },
        new()
        {
            Id = 3, Code = "MATH201", Title = "Linear Algebra",
            Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications. Emphasizes both computational techniques and theoretical understanding.",
            Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", DepartmentCode = "MATH", DepartmentName = "Mathematics",
            Instructor = new() { Name = "Dr. Emmy Noether", Title = "Professor", Email = "enoether@university.edu", Bio = "Dr. Noether is an award-winning mathematician whose research spans abstract algebra and theoretical physics. She is known for her engaging lecture style." },
            IsFeatured = true
        },
        new()
        {
            Id = 4, Code = "MATH101", Title = "Calculus I",
            Description = "Limits, derivatives, integrals, and the Fundamental Theorem of Calculus. Covers applications to physics, engineering, and economics.",
            Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", DepartmentCode = "MATH", DepartmentName = "Mathematics",
            Instructor = new() { Name = "Dr. Isaac Newton", Title = "Distinguished Professor", Email = "inewton@university.edu", Bio = "Dr. Newton brings decades of experience in applied mathematics. His teaching philosophy emphasizes intuition before rigor." },
            IsFeatured = false
        },
        new()
        {
            Id = 5, Code = "PHYS101", Title = "General Physics I",
            Description = "Mechanics, thermodynamics, and waves. Lecture and lab components cover Newtonian mechanics, energy conservation, and oscillatory motion with hands-on experiments.",
            Credits = 4, Schedule = "Tue/Thu 9:00–10:15 AM + Lab Fri 2:00–4:50 PM", DepartmentCode = "PHYS", DepartmentName = "Physics",
            Instructor = new() { Name = "Dr. Marie Curie", Title = "Professor", Email = "mcurie@university.edu", Bio = "Dr. Curie is a renowned physicist whose lab-centered teaching approach has won multiple university teaching awards." },
            IsFeatured = true
        },
        new()
        {
            Id = 6, Code = "PHYS301", Title = "Quantum Mechanics",
            Description = "Wave-particle duality, the Schrödinger equation, quantum states, measurement theory, and applications to atomic and molecular systems.",
            Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", DepartmentCode = "PHYS", DepartmentName = "Physics",
            Instructor = new() { Name = "Dr. Richard Feynman", Title = "Professor", Email = "rfeynman@university.edu", Bio = "Dr. Feynman is celebrated for making complex physics intuitive. He uses demonstrations and humor to bring quantum concepts to life." },
            IsFeatured = false
        },
        new()
        {
            Id = 7, Code = "ENG101", Title = "English Composition",
            Description = "Develops college-level writing skills through essay assignments, peer review, and revision. Covers argumentation, research writing, and critical reading.",
            Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", DepartmentCode = "ENG", DepartmentName = "English",
            Instructor = new() { Name = "Dr. Maya Angelou", Title = "Professor", Email = "mangelou@university.edu", Bio = "Dr. Angelou is a published author and poet who brings a creative perspective to academic writing instruction." },
            IsFeatured = false
        },
        new()
        {
            Id = 8, Code = "HIST201", Title = "World History: 1500 to Present",
            Description = "A survey of global history from the Age of Exploration through the modern era, examining political, economic, and cultural transformations across continents.",
            Credits = 3, Schedule = "Tue/Thu 10:30–11:45 AM", DepartmentCode = "HIST", DepartmentName = "History",
            Instructor = new() { Name = "Dr. Howard Zinn", Title = "Associate Professor", Email = "hzinn@university.edu", Bio = "Dr. Zinn focuses on people's history and encourages students to examine events from multiple perspectives." },
            IsFeatured = true
        },
        new()
        {
            Id = 9, Code = "CS201", Title = "Data Structures and Algorithms",
            Description = "In-depth study of arrays, linked lists, trees, graphs, sorting, searching, and algorithm complexity analysis. Extensive programming assignments in Java.",
            Credits = 3, Schedule = "Tue/Thu 3:00–4:15 PM", DepartmentCode = "CS", DepartmentName = "Computer Science",
            Instructor = new() { Name = "Dr. Donald Knuth", Title = "Professor", Email = "dknuth@university.edu", Bio = "Dr. Knuth is a pioneer in algorithm analysis. His courses are rigorous and deeply rewarding for students who enjoy problem solving." },
            IsFeatured = false
        },
        new()
        {
            Id = 10, Code = "BIO101", Title = "Introduction to Biology",
            Description = "Cell biology, genetics, evolution, and ecology. Lab sections provide hands-on experience with microscopy, DNA extraction, and ecological field studies.",
            Credits = 4, Schedule = "Mon/Wed 10:00–10:50 AM + Lab Thu 1:00–3:50 PM", DepartmentCode = "BIO", DepartmentName = "Biology",
            Instructor = new() { Name = "Dr. Charles Darwin", Title = "Professor", Email = "cdarwin@university.edu", Bio = "Dr. Darwin's research in evolutionary biology informs his teaching. He leads popular field trips that connect classroom concepts to the natural world." },
            IsFeatured = true
        }
    ];

    public Task<List<Course>> GetCoursesAsync(string? searchTerm = null, string? departmentCode = null)
    {
        var query = Courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(departmentCode))
        {
            query = query.Where(c => c.DepartmentCode.Equals(departmentCode, StringComparison.OrdinalIgnoreCase));
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            query = query.Where(c =>
                c.Title.Contains(searchTerm, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(searchTerm, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(searchTerm, StringComparison.OrdinalIgnoreCase));
        }

        return Task.FromResult(query.OrderBy(c => c.Code).ToList());
    }

    public Task<Course?> GetCourseByIdAsync(int id)
    {
        return Task.FromResult(Courses.FirstOrDefault(c => c.Id == id));
    }

    public Task<List<Course>> GetFeaturedCoursesAsync()
    {
        return Task.FromResult(Courses.Where(c => c.IsFeatured).ToList());
    }

    public Task<List<Department>> GetDepartmentsAsync()
    {
        var departments = Courses
            .GroupBy(c => c.DepartmentCode)
            .Select(g => new Department
            {
                Code = g.Key,
                Name = g.First().DepartmentName,
                CourseCount = g.Count()
            })
            .OrderBy(d => d.Name)
            .ToList();

        return Task.FromResult(departments);
    }

    public Task<bool> SubmitEnrollmentAsync(EnrollmentRequest request)
    {
        // In production, this would persist to a database
        return Task.FromResult(true);
    }
}

