            .GroupBy(c => c.DepartmentCode)
            .Select(g => new Department
            {
                Code = g.Key,
                Name = g.First().DepartmentName,
                CourseCount = g.Count()
            })
            .OrderBy(d => d.Name)
            .ToList();

        return Task.FromResult(departments);
    }

