toolArgs.file_text:
@page "/courses/{CourseId:int}"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models

<PageTitle>@(_course?.Title ?? "Course Details")</PageTitle>

@if (_course is null)
{
    <div class="alert alert-warning">Course not found.</div>
    <a href="courses" class="btn btn-outline-primary">Back to Catalog</a>
}
else
{
    <nav aria-label="breadcrumb" class="mb-3">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="courses">Catalog</a></li>
            <li class="breadcrumb-item"><a href="courses?dept=@_course.DepartmentCode">@_course.DepartmentName</a></li>
            <li class="breadcrumb-item active" aria-current="page">@_course.Code</li>
        </ol>
    </nav>

    <div class="row">
        <div class="col-lg-8">
            <h1>@_course.Title</h1>
            <div class="d-flex gap-2 mb-3">
                <span class="badge bg-primary fs-6">@_course.Code</span>
                <span class="badge bg-secondary fs-6">@_course.Credits credits</span>
                <span class="badge bg-info text-dark fs-6">@_course.DepartmentName</span>
            </div>

            <h4>Description</h4>
            <p class="mb-4">@_course.Description</p>

            <h4>Schedule</h4>
            <p class="mb-4">@_course.Schedule</p>

            <a href="enroll?courseId=@_course.Id" class="btn btn-primary">Enroll in This Course</a>
        </div>
        <div class="col-lg-4">
            <h4 class="mb-3">Instructor</h4>
            <InstructorBio Instructor="_course.Instructor" />
        </div>
    </div>
}

@code {
    [Parameter] public int CourseId { get; set; }
    [Inject] private ICatalogService CatalogService { get; set; } = default!;

    private Course? _course;

    protected override async Task OnInitializedAsync()
    {
        _course = await CatalogService.GetCourseByIdAsync(CourseId);
    }
}

toolArgs.new_str:
@page "/"
@using UniversityCourseCatalog.Services

<PageTitle>University Course Catalog</PageTitle>

<div class="text-center mb-5">
    <h1 class="display-4">University Course Catalog</h1>
    <p class="lead text-muted">Explore our departments, discover courses, and enroll for the upcoming semester.</p>
    <a href="courses" class="btn btn-primary btn-lg me-2">Browse All Courses</a>
    <a href="enroll" class="btn btn-outline-secondary btn-lg">Enroll Now</a>
</div>

@if (_featuredCourses is not null && _departments is not null)
{
    <FeaturedCourses Courses="_featuredCourses" />
    <DepartmentLinks Departments="_departments" />
}

@code {
    [Inject] private ICatalogService CatalogService { get; set; } = default!;

    private List<Models.Course>? _featuredCourses;
    private List<Models.Department>? _departments;

    protected override async Task OnInitializedAsync()
    {
        _featuredCourses = await CatalogService.GetFeaturedCoursesAsync();
        _departments = await CatalogService.GetDepartmentsAsync();
    }
}

toolArgs.file_text:
@page "/enroll"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models

<PageTitle>Enrollment Request</PageTitle>

<h1 class="mb-4">Enrollment Request</h1>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>Your enrollment request has been received. You will be notified of your enrollment status via your university email.</p>
        <hr />
        <a href="courses" class="btn btn-outline-success">Browse More Courses</a>
    </div>
}
else
{
    <div class="row">
        <div class="col-lg-6">
            <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="enrollment">
                <DataAnnotationsValidator />
                <AntiforgeryToken />

                <div class="mb-3">
                    <label for="fullName" class="form-label">Full Name</label>
                    <InputText id="fullName" class="form-control" @bind-Value="_model.FullName" />
                    <ValidationMessage For="() => _model.FullName" />
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID</label>
                    <InputText id="studentId" class="form-control" @bind-Value="_model.StudentId" />
                    <ValidationMessage For="() => _model.StudentId" />
                    <div class="form-text">Format: 2 uppercase letters followed by 6 digits (e.g., CS123456)</div>
                </div>

                <div class="mb-3">
                    <label for="courseSelect" class="form-label">Course</label>
                    <InputSelect id="courseSelect" class="form-select" @bind-Value="_model.CourseId">
                        <option value="0">— Select a course —</option>
                        @foreach (var course in _courses)
                        {
                            <option value="@course.Id">@course.Code — @course.Title</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => _model.CourseId" />
                </div>

                <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
            </EditForm>
        </div>
    </div>
}

@code {
    [Inject] private ICatalogService CatalogService { get; set; } = default!;

    [SupplyParameterFromQuery(Name = "courseId")]
    private int? PreselectedCourseId { get; set; }

    [SupplyParameterFromForm]
    private EnrollmentRequest _model { get; set; } = new();

    private List<Course> _courses = [];
    private bool _submitted;

    protected override async Task OnInitializedAsync()
    {
        _courses = await CatalogService.GetCoursesAsync();

        if (PreselectedCourseId.HasValue && _model.CourseId == 0)
        {
            _model.CourseId = PreselectedCourseId.Value;
        }
    }

    private async Task HandleSubmit()
    {
        await CatalogService.SubmitEnrollmentAsync(_model);
        _submitted = true;
    }
}

